-- ============================================================
-- 宠物店管理系统：1 个月业务测试数据（尽量还原真实场景）
-- 数据时间范围：2025-01-14 ~ 2025-02-13
-- 执行前请确保已执行：pet_manager.sql、migrate_logic_delete_and_balance.sql
-- 若已执行 migrate_member_lifecycle.sql，member 表含 last_consume_time、tags，可留空
--
-- 前提：本脚本假设业务表（member、goods、pet、recharge_record、order_main、
--       order_item、vaccine_record、medical_record、claim_record、purchase_record、
--       inventory_flow）当前为空；若库中已有数据请先备份并在测试库执行或清空后执行。
-- ============================================================
SET NAMES utf8mb4;
USE pet_manager;

-- ---------------------------------------------------------------------------
-- 1. 会员（约 28 人，注册时间分散在 1 个月内，部分有余额与等级）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 2. 商品（猫粮狗粮、零食、用品、药品等，价格与库存不一）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 3. 宠物档案（关联会员，猫狗为主，品种与生日分散）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 4. 会员充值记录（时间与金额分散，部分有备注如活动）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 5. 订单主表（混合状态：待付款、已付款、已完成，时间分散）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 6. 订单明细（每单 1～3 个商品，数量与单价不一）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 7. 采购记录（须在入库前插入，供应商、批次、数量与金额分散）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 8. 采购入库：按采购单增加库存并写入入库流水
-- ---------------------------------------------------------------------------
UPDATE goods g SET g.stock = g.stock + IFNULL((
  SELECT SUM(pr.quantity) FROM purchase_record pr WHERE pr.goods_id = g.id AND pr.deleted = 0
), 0);

SELECT CONCAT('IN', pr.id), pr.goods_id, pr.goods_name, '入库', pr.quantity, pr.purchase_no, CONCAT(pr.purchase_date, ' 12:00:00'), pr.create_time
FROM purchase_record pr WHERE pr.deleted = 0;

-- ---------------------------------------------------------------------------
-- 9. 已完成/已付款订单：扣减商品库存并写出库流水
-- ---------------------------------------------------------------------------
UPDATE goods g SET g.stock = g.stock - IFNULL((
  SELECT SUM(oi.quantity) FROM order_item oi
  INNER JOIN order_main o ON oi.order_id = o.id AND o.deleted = 0
  WHERE o.status IN ('已完成','已付款') AND oi.goods_id = g.id
), 0);

SELECT CONCAT('IF', o.id, '_', oi.id), oi.goods_id, oi.goods_name, '出库', oi.quantity, o.order_no, o.order_time, NOW()
FROM order_item oi
INNER JOIN order_main o ON oi.order_id = o.id
WHERE o.status IN ('已完成','已付款') AND o.deleted = 0;

-- ---------------------------------------------------------------------------
-- 10. 疫苗记录（多只宠物、多种疫苗、日期分散）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 11. 医疗记录（常见症状与处置，费用不一）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 12. 索赔记录（少量，与宠物/事件日期关联）
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 说明：会员/宠物/订单/充值/疫苗/医疗/索赔/采购 时间均分布在 2025-01-14～2025-02-13 约一个月内。
-- 库存逻辑：商品初始 0 → 采购入库增加 → 已完成/已付款订单出库扣减。若表有 balance/deleted/last_consume_time 等扩展列可留空或由业务更新。
-- ============================================================
